  88: func buildIndependentHotLaneCandidates(previousWorld WorldWireFullPacket, currentWorld WorldWireFullPacket, state RealtimeSessionState) ([]RealtimeLaneCandidate, HotLaneCohortState) {
  89: 	cohortState := state.HotLaneCohorts
