 60: func (state *RealtimeSessionState) UpdateLane(lane Lane, metadata Metadata) {
 61: 	if existing, ok := state.Lanes[lane]; ok && metadata.Sequence < existing.Sequence {
 62: 		return
 63: 	}
 64: 	state.Lanes[lane] = RealtimeLaneState{
 65: 		Lane:         lane,
 66: 		SnapshotKind: metadata.SnapshotKind,
 67: 		Sequence:     metadata.Sequence,
 68: 		BaselineID:   metadata.BaselineID,
 69: 		SnapshotID:   metadata.SnapshotID,
 70: 		ChunkIndex:   metadata.ChunkIndex,
 71: 		ChunkCount:   metadata.ChunkCount,
 72: 		IsFinalChunk: metadata.IsFinalChunk,
 73: 	}
 74: }
